SET NAMES utf8mb4;

USE `db_user`;

-- 用户（演示账号密码统一为 VALOR_123456，BCrypt 加密）
ON DUPLICATE KEY UPDATE `id` = `id`;

-- 商家
ON DUPLICATE KEY UPDATE `id` = `id`;

-- 商家审核记录

-- 商家保证金账户
ON DUPLICATE KEY UPDATE `merchant_id` = `merchant_id`;

-- 用户内部资金账户（可用 / 待结算 / 冻结）
ON DUPLICATE KEY UPDATE `user_id` = `user_id`;

-- 平台内部账户
ON DUPLICATE KEY UPDATE `id` = `id`;

-- 手续费配置（类目 x 商家等级）
ON DUPLICATE KEY UPDATE `category_id` = `category_id`;

-- 商家信用统计
ON DUPLICATE KEY UPDATE `merchant_id` = `merchant_id`;

-- 商家信用变动幂等流水
ON DUPLICATE KEY UPDATE `operation_key` = `operation_key`;

-- 资金交易头
ON DUPLICATE KEY UPDATE `transaction_no` = `transaction_no`;

-- 资金流水明细（balance_after 为账户实时余额口径，平台/外部账户为 NULL）
ON DUPLICATE KEY UPDATE `id` = `id`;

-- 提现申请
ON DUPLICATE KEY UPDATE `withdraw_no` = `withdraw_no`;

-- 资金对账差异（MANUAL_REVIEW / FROZEN 提现与既有对账口径不一致，供人工处理）
